    reopen_count smallint DEFAULT '0'::smallint NOT NULL,
    created_at timestamp(0) with time zone,
    updated_at timestamp(0) with time zone,
    CONSTRAINT concerns_category_check CHECK (((category)::text = ANY ((ARRAY['tax'::character varying, 'accounting'::character varying, 'legal'::character varying, 'social'::character varying, 'training'::character varying, 'administrative'::character varying, 'public_platforms'::character varying, 'document_request'::character varying, 'info_update'::character varying, 'closing_pieces'::character varying, 'other'::character varying])::text[]))),
    CONSTRAINT concerns_counters CHECK (((target_response_days > 0) AND (reopen_count >= 0))),
    CONSTRAINT concerns_level_check CHECK (((level)::text = ANY ((ARRAY['member_to_cga'::character varying, 'cga_to_cncga'::character varying])::text[]))),
    CONSTRAINT concerns_member_level CHECK ((((level)::text = 'member_to_cga'::text) = (member_id IS NOT NULL))),
    CONSTRAINT concerns_rejection CHECK ((((status)::text <> 'rejected'::text) OR (rejection_reason IS NOT NULL))),
    CONSTRAINT concerns_status_check CHECK (((status)::text = ANY ((ARRAY['open'::character varying, 'in_review'::character varying, 'resolved'::character varying, 'rejected'::character varying])::text[]))),
    CONSTRAINT concerns_transfer_levels CHECK ((((transferred_to_concern_id IS NULL) OR ((level)::text = 'member_to_cga'::text)) AND ((transferred_from_concern_id IS NULL) OR ((level)::text = 'cga_to_cncga'::text))))
);


