    CONSTRAINT members_legal_form_check CHECK (((legal_form)::text = ANY ((ARRAY['SARL'::character varying, 'SARLU'::character varying, 'SAS'::character varying, 'SASU'::character varying, 'SA'::character varying, 'SNC'::character varying, 'GIE'::character varying, 'COOP'::character varying, 'EI'::character varying, 'OTHER'::character varying])::text[]))),
    CONSTRAINT members_ncc_format CHECK (((ncc)::text ~ '^[0-9]{7}[A-Z]$'::text)),
