    CONSTRAINT members_portfolio_check CHECK (((portfolio)::text = ANY ((ARRAY['cga'::character varying, 'cabinet'::character varying])::text[]))),
    CONSTRAINT members_referrer_cga_only CHECK (((referrer_id IS NULL) OR ((portfolio)::text = 'cga'::text))),
    CONSTRAINT members_regime_check CHECK (((regime)::text = ANY ((ARRAY['RME'::character varying, 'TEE'::character varying, 'RSI'::character varying, 'RNI'::character varying])::text[]))),
    CONSTRAINT members_status_check CHECK (((status)::text = ANY ((ARRAY['draft'::character varying, 'active'::character varying, 'radiation_pending'::character varying, 'radiated'::character varying, 'closed'::character varying])::text[])))
);


