--
-- Name: stat_network_monthly; Type: MATERIALIZED VIEW; Schema: public; Owner: -
--

CREATE MATERIALIZED VIEW public.stat_network_monthly AS
 WITH bounds AS (
         SELECT make_date(LEAST(COALESCE((( SELECT min(network_dues.year) AS min
                   FROM public.network_dues))::integer, (EXTRACT(year FROM CURRENT_DATE))::integer), COALESCE((( SELECT min(quarterly_reports.year) AS min
                   FROM public.quarterly_reports))::integer, (EXTRACT(year FROM CURRENT_DATE))::integer), (EXTRACT(year FROM CURRENT_DATE))::integer), 1, 1) AS first_month
        ), months AS (
         SELECT (series.series)::date AS month,
            (((series.series + '1 mon'::interval) - '1 day'::interval))::date AS month_end
           FROM bounds,
            LATERAL generate_series((bounds.first_month)::timestamp with time zone, ((date_trunc('month'::text, (CURRENT_DATE)::timestamp with time zone))::date)::timestamp with time zone, '1 mon'::interval) series(series)
        )
 SELECT month,
    month_end,
    (( SELECT count(*) AS count
           FROM public.organizations o
          WHERE (((o.type)::text = 'cga'::text) AND (o.deleted_at IS NULL) AND ((o.created_at)::date <= months.month_end) AND (NOT (EXISTS ( SELECT 1
                   FROM public.organization_status_events e
                  WHERE ((e.organization_id = o.id) AND ((e.event)::text = 'terminated'::text) AND ((e.occurred_at)::date <= months.month_end))))))))::integer AS total_cgas,
    (( SELECT count(*) AS count
           FROM public.organizations o
          WHERE (((o.type)::text = 'cga'::text) AND (o.deleted_at IS NULL) AND ((o.subscription_status)::text <> 'none'::text) AND (o.subscription_started_at <= months.month_end) AND ((o.subscription_ended_at IS NULL) OR (o.subscription_ended_at > months.month_end)))))::integer AS subscribed_cgas,
    (COALESCE(( SELECT sum(d.amount_due) AS sum
           FROM public.network_dues d
          WHERE (d.year = (EXTRACT(year FROM months.month))::integer)), (0)::numeric))::bigint AS dues_expected,
    (COALESCE(( SELECT sum(p.amount) AS sum
           FROM public.network_due_payments p
          WHERE (((p.status)::text = 'confirmed'::text) AND ((p.paid_on >= months.month) AND (p.paid_on <= months.month_end)))), (0)::numeric))::bigint AS dues_collected,
    (COALESCE(( SELECT sum(p.amount) AS sum
           FROM (public.network_due_payments p
             JOIN public.network_dues d ON ((d.id = p.network_due_id)))
          WHERE (((p.status)::text = 'confirmed'::text) AND (d.year = (EXTRACT(year FROM months.month))::integer) AND (p.paid_on <= months.month_end))), (0)::numeric))::bigint AS dues_collected_year_to_date,
    (( SELECT count(*) AS count
           FROM public.network_dues d
          WHERE ((d.year = (EXTRACT(year FROM months.month))::integer) AND ((d.status)::text = 'paid'::text))))::integer AS dues_paid_cgas,
    (( SELECT count(*) AS count
           FROM public.quarterly_reports r
          WHERE ((r.deadline >= months.month) AND (r.deadline <= months.month_end))))::integer AS reports_due,
    (( SELECT count(*) AS count
           FROM public.quarterly_reports r
          WHERE ((r.transmitted_at IS NOT NULL) AND (((r.transmitted_at)::date >= months.month) AND ((r.transmitted_at)::date <= months.month_end)))))::integer AS reports_transmitted,
    (( SELECT count(*) AS count
           FROM public.quarterly_reports r
          WHERE ((r.transmitted_at IS NOT NULL) AND (((r.transmitted_at)::date >= months.month) AND ((r.transmitted_at)::date <= months.month_end)) AND ((r.transmitted_at)::date > r.deadline))))::integer AS reports_transmitted_late,
    now() AS computed_at
   FROM months
  WITH NO DATA;


