--
-- Name: training_registrations; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.training_registrations (
    id character(26) NOT NULL,
    organization_id character(26) NOT NULL,
    training_id character(26) NOT NULL,
    membership_id character(26) NOT NULL,
    user_id character(26) NOT NULL,
    member_id character(26),
    registered_by character(26) NOT NULL,
    status character varying(20) NOT NULL,
    waitlist_position integer,
    rejection_reason text,
    payment_status character varying(20) DEFAULT 'not_applicable'::character varying NOT NULL,
    paid_on date,
    payment_method character varying(20),
    payment_reference character varying(100),
    receipt_number character varying(40),
    receipt_document_id character(26),
    attendance character varying(10),
    certificate_document_id character(26),
    evaluation_score smallint,
    evaluation_comment text,
    evaluated_at timestamp(0) with time zone,
    promoted_at timestamp(0) with time zone,
    reminded_at timestamp(0) with time zone,
    cancelled_at timestamp(0) with time zone,
    created_at timestamp(0) with time zone,
    updated_at timestamp(0) with time zone,
    CONSTRAINT training_registrations_attendance_check CHECK (((attendance)::text = ANY ((ARRAY['present'::character varying, 'absent'::character varying])::text[]))),
    CONSTRAINT training_registrations_cancelled CHECK ((((status)::text <> 'cancelled'::text) OR (cancelled_at IS NOT NULL))),
    CONSTRAINT training_registrations_paid CHECK ((((payment_status)::text <> 'paid'::text) OR ((paid_on IS NOT NULL) AND (payment_method IS NOT NULL) AND (receipt_number IS NOT NULL)))),
    CONSTRAINT training_registrations_payment_method_check CHECK (((payment_method)::text = ANY ((ARRAY['cash'::character varying, 'cheque'::character varying, 'transfer'::character varying, 'mobile_money'::character varying, 'other'::character varying])::text[]))),
    CONSTRAINT training_registrations_payment_status_check CHECK (((payment_status)::text = ANY ((ARRAY['not_applicable'::character varying, 'to_pay'::character varying, 'paid'::character varying])::text[]))),
    CONSTRAINT training_registrations_score CHECK (((evaluation_score IS NULL) OR ((evaluation_score >= 1) AND (evaluation_score <= 5)))),
    CONSTRAINT training_registrations_status_check CHECK (((status)::text = ANY ((ARRAY['pending_approval'::character varying, 'registered'::character varying, 'waitlisted'::character varying, 'cancelled'::character varying, 'rejected'::character varying])::text[]))),
    CONSTRAINT training_registrations_waitlist CHECK ((((status)::text = 'waitlisted'::text) = (waitlist_position IS NOT NULL)))
);


--
-- Name: trainings; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.trainings (
    id character(26) NOT NULL,
    organization_id character(26) NOT NULL,
    title character varying(200) NOT NULL,
    description text,
    format character varying(20) NOT NULL,
    location character varying(255),
    online_url character varying(500),
    trainer character varying(200),
    starts_at timestamp(0) with time zone NOT NULL,
    ends_at timestamp(0) with time zone NOT NULL,
    capacity integer,
    price bigint DEFAULT '0'::bigint NOT NULL,
    requires_approval boolean DEFAULT false NOT NULL,
    status character varying(20) DEFAULT 'draft'::character varying NOT NULL,
    published_at timestamp(0) with time zone,
    cancellation_reason text,
    cancelled_at timestamp(0) with time zone,
    completed_at timestamp(0) with time zone,
    created_by character(26) NOT NULL,
    created_at timestamp(0) with time zone,
    updated_at timestamp(0) with time zone,
    CONSTRAINT trainings_amounts CHECK (((price >= 0) AND ((capacity IS NULL) OR (capacity > 0)))),
    CONSTRAINT trainings_cancellation CHECK ((((status)::text <> 'cancelled'::text) OR ((cancelled_at IS NOT NULL) AND (cancellation_reason IS NOT NULL)))),
    CONSTRAINT trainings_dates CHECK ((ends_at >= starts_at)),
    CONSTRAINT trainings_format_check CHECK (((format)::text = ANY ((ARRAY['in_person'::character varying, 'online'::character varying, 'workshop'::character varying])::text[]))),
    CONSTRAINT trainings_status_check CHECK (((status)::text = ANY ((ARRAY['draft'::character varying, 'published'::character varying, 'cancelled'::character varying, 'completed'::character varying])::text[])))
);


